fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Since we assume the two input vectors have equal length,
    // we can directly zip their iterators.
    arr1.iter()
        .zip(arr2.iter())
        .map(|(&x, &y)| x ^ y)
        .collect()
}